import * as THREE from 'three';

const bilingual=(ko,en)=>`${ko} (${en})`;
const number=n=>n.toLocaleString('ko-KR');
const coordinates=ll=>`${ll[1].toFixed(5)}° N, ${ll[0].toFixed(5)}° E`;
const emptyGroup=g=>{while(g.children.length){const c=g.children[0];g.remove(c);c.geometry?.dispose();if(Array.isArray(c.material))c.material.forEach(m=>m.dispose());else c.material?.dispose();}};

export function createHikingExplorer(dataset,ctx){
 const {scene,camera,toWorld,groundHeight,$,stopTour,flyTo,closeExplore,setLocation,clearPlaceSelection}=ctx;
 const {mountains,sections,routes,meta}=dataset;
 let activeMountain=null,activeRoute=null,selectedKind='connection',trailsVisible=true,endpointsVisible=true,activeTab='trails';
 const root=new THREE.Group();root.name='Mapped hiking trails';scene.add(root);
 const overviewGroup=new THREE.Group(),mountainGroup=new THREE.Group(),selectedGroup=new THREE.Group(),endpointGroup=new THREE.Group();root.add(overviewGroup,mountainGroup,selectedGroup,endpointGroup);
 const markerLabels=[];const matrix=new THREE.Object3D();const projected=new THREE.Vector3();
 const converted=new Map();
 function pointsFor(r){if(!converted.has(r.id)){const p=r.points.map(ll=>{const [x,z]=toWorld(...ll);return new THREE.Vector3(x,groundHeight(x,z)+.045,z);});converted.set(r.id,p);}return converted.get(r.id);}
 function sampled(points){const out=[];for(let i=0;i<points.length-1;i++){const a=points[i],b=points[i+1],steps=Math.max(1,Math.ceil(Math.hypot(b.x-a.x,b.z-a.z)/.035));for(let j=0;j<steps;j++){const t=j/steps,x=THREE.MathUtils.lerp(a.x,b.x,t),z=THREE.MathUtils.lerp(a.z,b.z,t);out.push(new THREE.Vector3(x,groundHeight(x,z)+.045,z));}}out.push(points.at(-1));return out;}
 function linesFor(records,color,opacity){const array=[];for(const r of records){const pts=sampled(pointsFor(r));for(let i=1;i<pts.length;i++)array.push(...pts[i-1].toArray(),...pts[i].toArray());}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(array,3));const line=new THREE.LineSegments(geometry,new THREE.LineBasicMaterial({color,transparent:true,opacity,depthWrite:false}));line.renderOrder=5;return line;}
 const allLines=linesFor(sections,'#ab7933',.55);overviewGroup.add(allLines);
 function ribbon(record,width,color,lift){const pts=sampled(pointsFor(record)),array=[];for(let i=1;i<pts.length;i++){const a=pts[i-1],b=pts[i],dx=b.x-a.x,dz=b.z-a.z,len=Math.hypot(dx,dz);if(len<1e-7)continue;const nx=-dz/len*width,nz=dx/len*width;const side=(p,s)=>{const x=p.x+nx*s,z=p.z+nz*s;return[x,groundHeight(x,z)+lift,z];};const a1=side(a,1),a2=side(a,-1),b1=side(b,1),b2=side(b,-1);array.push(...a1,...b1,...a2,...a2,...b1,...b2);}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(array,3));const mesh=new THREE.Mesh(geometry,new THREE.MeshBasicMaterial({color,side:THREE.DoubleSide,depthWrite:false}));mesh.renderOrder=8;return mesh;}
 function clearMarkers(){for(const m of markerLabels)m.el.remove();markerLabels.length=0;emptyGroup(endpointGroup);}
 function addMarker(ll,isFinish){const [x,z]=toWorld(...ll),y=groundHeight(x,z)+.09,color=isFinish?'#c64c2e':'#16825d';const geo=new THREE.SphereGeometry(.075,10,7);const marker=new THREE.Mesh(geo,new THREE.MeshBasicMaterial({color,depthTest:false}));marker.position.set(x,y+.04,z);marker.renderOrder=13;endpointGroup.add(marker);const pole=new THREE.Mesh(new THREE.CylinderGeometry(.014,.014,.25,6),new THREE.MeshBasicMaterial({color,depthTest:false}));pole.position.set(x,y+.15,z);pole.renderOrder=12;endpointGroup.add(pole);
  const el=document.createElement('button');el.className='trail-map-label'+(isFinish?' finish':'');el.textContent=isFinish?'도착 (Finish)':'출발 (Start)';el.setAttribute('aria-label',(isFinish?'도착점으로 이동 (Go to finish)':'출발점으로 이동 (Go to start)')+' · '+coordinates(ll));el.onclick=()=>focusEndpoint(isFinish);el.hidden=true;$('labels').append(el);markerLabels.push({el,position:new THREE.Vector3(x,y+.34,z),isFinish});
 }
 function mountainEndpoints(records){if(!records.length)return;const geom=new THREE.SphereGeometry(.022,5,4);for(const finish of [false,true]){const mesh=new THREE.InstancedMesh(geom.clone(),new THREE.MeshBasicMaterial({color:finish?'#c96737':'#2a9479'}),records.length);records.forEach((r,i)=>{const point=pointsFor(r)[finish?r.points.length-1:0];matrix.position.copy(point);matrix.position.y+=.04;matrix.scale.setScalar(1);matrix.updateMatrix();mesh.setMatrixAt(i,matrix.matrix);});mesh.instanceMatrix.needsUpdate=true;mesh.name=finish?'All selected mountain section finishes':'All selected mountain section starts';endpointGroup.add(mesh);}geom.dispose();}
 function populateMountains(){const major=document.createElement('optgroup');major.label='주요 산 (Main mountains)';const rest=document.createElement('optgroup');rest.label='모든 산·봉우리 (All mountains and peaks)';$('mountain').replaceChildren(major,rest);for(const m of [...mountains].sort((a,b)=>a.name.localeCompare(b.name,'ko')||a.ll[0]-b.ll[0])){const o=document.createElement('option');o.value=m.id;o.textContent=`${bilingual(m.name,m.en)} · ${Math.round(m.elevation)} m${m.sectionIds.length?'':' · 경로 없음 (No paths)'}`;(m.major?major:rest).append(o);}}
 function setOption(group,value,label){const o=document.createElement('option');o.value=value;o.textContent=label;group.append(o);}
 function sectionName(s,index){return s.name?bilingual(s.name,s.en||'Mapped trail'):`등산로 구간 ${index+1} (Trail section ${index+1})`;}
 function selectMountain(id,focus=false){activeMountain=mountains.find(m=>m.id===id);if(!activeMountain)return;$('mountain').value=id;const m=activeMountain;$('trail-route').replaceChildren();const mapped=document.createElement('optgroup');mapped.label='정상 연결 경로 (Summit connections)';for(const ri of m.routeIds){const r=routes[ri];setOption(mapped,'r:'+ri,`${bilingual(r.startName,r.startEn)} → ${bilingual(r.endName,r.endEn)} · ${r.lengthKm.toFixed(2)} km`);}if(mapped.children.length)$('trail-route').append(mapped);
  const raw=document.createElement('optgroup');raw.label='모든 등산로 구간 (All mapped sections)';for(const si of m.sectionIds){const s=sections[si];setOption(raw,'s:'+si,`${sectionName(s,si)} · ${s.lengthKm.toFixed(2)} km`);}if(raw.children.length)$('trail-route').append(raw);
  emptyGroup(mountainGroup);const chosen=m.sectionIds.map(i=>sections[i]);if(chosen.length)mountainGroup.add(linesFor(chosen,'#bd7420',1));$('trail-route').disabled=!chosen.length&&!m.routeIds.length;
  $('trail-summary').textContent=`전체 ${number(meta.mountainCount)}개 산·봉우리 / ${number(meta.sectionCount)}개 구간 (peaks / sections) · 선택한 산 주변 ${number(m.sectionIds.length)}개 구간 / 정상 연결 ${m.routeIds.length}개 (nearby sections / summit connections)`;
  if($('trail-route').value)selectRoute($('trail-route').value,focus);else{activeRoute=null;clearMarkers();emptyGroup(selectedGroup);$('trail-details').hidden=true;const option=document.createElement('option');option.textContent='등록된 경로가 없습니다 (No mapped routes)';$('trail-route').append(option);if(focus){stopTour();clearPlaceSelection();const [x,z]=toWorld(...m.ll);flyTo(x,z,groundHeight(x,z),m.radiusKm);setLocation(bilingual(m.name,m.en),'산·봉우리 (Mountain / peak)','이 봉우리 주변에는 표시할 수 있는 등산로가 없습니다. (No mapped trails available.)',m.ll,'산 (Peak)');}}
 }
 function routeRecord(value){const [kind,index]=value.split(':');return{kind,record:(kind==='r'?routes:sections)[Number(index)]};}
 function selectRoute(value,focus=true){const {kind,record}=routeRecord(value);if(!record)return;activeRoute=record;selectedKind=kind;$('trail-route').value=value;emptyGroup(selectedGroup);clearMarkers();selectedGroup.add(ribbon(record,.030,'#ffffe6',.055),ribbon(record,.018,'#de9324',.065));mountainEndpoints(activeMountain.sectionIds.map(i=>sections[i]));addMarker(record.points[0],false);addMarker(record.points.at(-1),true);
  const summit=kind==='r';const label=summit?bilingual(record.name,record.en):sectionName(record,sections.indexOf(record));$('trail-title').textContent=label;$('trail-start-name').textContent=summit?bilingual(record.startName,record.startEn):'구간 시작점 (Section start)';$('trail-end-name').textContent=summit?bilingual(record.endName,record.endEn):'구간 끝점 (Section finish)';$('trail-start-coordinates').textContent=coordinates(record.points[0]);$('trail-end-coordinates').textContent=coordinates(record.points.at(-1));$('trail-distance').textContent=`지도 경로 길이 (Mapped distance) · ${record.lengthKm.toFixed(2)} km${summit?' · 연결된 길을 따르는 탐색 경로 (Exploratory connection)':' · 원본 구간의 첫점 → 끝점 (Source first → last point)'}${summit&&record.summitGapM>=20?` · 정상까지 직선 ${Math.round(record.summitGapM)} m 지점에서 종료 (Ends near summit)`:''}`;
  $('trail-source').href=summit?`https://www.openstreetmap.org/node/${activeMountain.id}`:`https://www.openstreetmap.org/way/${record.wayId}`;$('trail-details').hidden=false;refreshVisibility();if(focus){fitRoute();closeExplore();}
 }
 function fitRoute(){if(!activeRoute)return;stopTour();clearPlaceSelection();trailsVisible=true;$('show-trails').checked=true;refreshVisibility();const pts=pointsFor(activeRoute);let minX=Infinity,maxX=-Infinity,minZ=Infinity,maxZ=-Infinity;for(const p of pts){minX=Math.min(minX,p.x);maxX=Math.max(maxX,p.x);minZ=Math.min(minZ,p.z);maxZ=Math.max(maxZ,p.z);}const x=(minX+maxX)/2,z=(minZ+maxZ)/2;flyTo(x,z,groundHeight(x,z),Math.max(maxX-minX,maxZ-minZ,.4)*.75);const r=activeRoute;setLocation(bilingual(activeMountain.name,activeMountain.en),'등산로 (Hiking trail)',`${selectedKind==='r'?r.startName:'출발 (Start)'} → ${selectedKind==='r'?r.endName:'도착 (Finish)'} · ${r.lengthKm.toFixed(2)} km`,r.points[0],'등산 (Hike)');}
 function focusEndpoint(finish){if(!activeRoute)return;stopTour();clearPlaceSelection();const ll=activeRoute.points[finish?activeRoute.points.length-1:0],[x,z]=toWorld(...ll);flyTo(x,z,groundHeight(x,z),.32);setLocation(finish?'도착점 (Finish)':'출발점 (Start)',bilingual(activeMountain.name,activeMountain.en),selectedKind==='r'?(finish?bilingual(activeRoute.endName,activeRoute.endEn):bilingual(activeRoute.startName,activeRoute.startEn)):'선택한 등산로 구간의 끝점입니다. (Endpoint of the selected mapped section.)',ll,'등산 (Hike)');closeExplore();}
 function refreshVisibility(){root.visible=trailsVisible&&activeTab!=='apts';endpointGroup.visible=trailsVisible&&endpointsVisible&&activeTab==='trails';mountainGroup.visible=activeTab==='trails';selectedGroup.visible=activeTab==='trails';allLines.material.opacity=activeTab==='trails'?.50:.34;for(const m of markerLabels)m.el.hidden=!endpointGroup.visible;}
 function setTab(tab,focus=false){activeTab=tab;$('explore').dataset.tab=tab;document.dispatchEvent(new CustomEvent('atlas-tab-change',{detail:tab}));for(const id of ['apts','places','trails']){const on=id===tab;const b=$('tab-'+id);b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;$(id+'-panel').hidden=!on;if(on&&focus)b.focus();}refreshVisibility();}
 const tabs=['apts','places','trails'];for(const id of tabs){$('tab-'+id).onclick=()=>setTab(id);$('tab-'+id).onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(tabs.indexOf(activeTab)+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setTab(tabs[next],true);}};}
 $('mountain').onchange=e=>selectMountain(e.target.value,true);$('trail-route').onchange=e=>selectRoute(e.target.value,true);$('show-trails').onchange=e=>{trailsVisible=e.target.checked;refreshVisibility();};$('show-endpoints').onchange=e=>{endpointsVisible=e.target.checked;refreshVisibility();};$('fit-trail').onclick=()=>{fitRoute();closeExplore();};$('trail-start').onclick=()=>focusEndpoint(false);$('trail-end').onclick=()=>focusEndpoint(true);$('trail-about').onclick=()=>$('about').showModal();
 $('trails-data-date').textContent=`데이터 시점 (Snapshot): ${meta.snapshot.replace('T',' ').replace('Z',' UTC')}`;
 $('trail-coverage-about').textContent=`등산로 (Hiking trails): ${meta.coverage}. OpenStreetMap에 등록된 ${number(meta.mountainCount)}개 산·봉우리 주변 ${number(meta.sectionCount)}개 등산·보행 구간과 ${number(meta.connectionCount)}개 정상 연결 경로를 표시합니다. 산별 목록은 정상 주변의 지리적 범위로 묶어 서로 겹칠 수 있습니다. 연결 경로는 원본 길을 따라 계산한 탐색용 경로이며 공식 지정 코스가 아닙니다. 구간의 첫점과 끝점은 산행 방향을 강제하지 않습니다. 미등록 길과 실시간 통제 상태는 반영되지 않을 수 있습니다. (Geographically grouped mapped paths and exploratory summit connections, not a complete or live trail inventory.) 기존 서울 지도 바깥은 지형과 등산로를 표시합니다. (Outer area shows terrain and trails.)`;
 populateMountains();const initial=mountains.find(m=>m.name.startsWith('북한산'))||mountains.find(m=>m.sectionIds.length);if(initial)selectMountain(initial.id,false);setTab('trails');
 function update(){if(!endpointGroup.visible){for(const m of markerLabels)m.el.hidden=true;return;}const points=[];for(const m of markerLabels){projected.copy(m.position).project(camera);const x=(projected.x*.5+.5)*innerWidth,y=(-projected.y*.5+.5)*innerHeight;points.push({m,x,y,z:projected.z});}const overlap=points.length===2&&Math.abs(points[0].x-points[1].x)<125&&Math.abs(points[0].y-points[1].y)<45;for(const {m,x,y,z} of points){const show=z>-1&&z<1&&x>12&&x<innerWidth-12&&y>10&&y<innerHeight-100;m.el.hidden=!show;if(show){m.el.style.left=THREE.MathUtils.clamp(x,65,innerWidth-65)+'px';m.el.style.top=(y+(overlap&&m.isFinish?43:0))+'px';}}}
 return{update,selectMountain,selectRoute,fitRoute,setTab,getState:()=>({mountains:meta.mountainCount,sections:meta.sectionCount,connections:meta.connectionCount,mountain:activeMountain?.id,route:activeRoute?.id,trailsVisible,endpointsVisible,activeTab})};
}
